package com.allstar.faithid.core.sync

/**
 * HTTP contract between kiosks and the DB server (protocol version 2).
 *
 * Every request except [HEALTH] and [AUTH_REQUEST] must carry [HEADER_CLIENT_ID] and an
 * `Authorization: Bearer <secret>` header. The secret is generated by the kiosk and never sent by
 * the server; the server stores only its SHA-256. Approval happens in the server app's UI, never
 * over HTTP.
 */
object Protocol {
    const val VERSION = 2

    const val HEALTH = "/api/health"
    const val AUTH_REQUEST = "/api/v2/auth/request"
    const val CHANGES = "/api/v2/changes"
    const val OPS = "/api/v2/ops"
    const val ATTENDANCE = "/api/v2/attendance"
    const val UPDATES_WS = "/ws/v2/updates"

    const val HEADER_CLIENT_ID = "X-Faith-Client-Id"
    const val HEADER_DEVICE_NAME = "X-Faith-Device-Name"
    const val HEADER_AUTHORIZATION = "Authorization"
    const val BEARER = "Bearer "

    const val PARAM_SINCE = "since"
    const val PARAM_EPOCH = "epoch"

    /** Status values in the [AUTH_REQUEST] response. */
    const val AUTH_APPROVED = "approved"
    const val AUTH_PENDING = "pending"

    /** Largest request body the server accepts (registrations carry many 2 KB samples). */
    const val MAX_BODY_BYTES = 32L * 1024 * 1024
}

/**
 * Plain-text `key=value` lines used for small responses and WebSocket messages. Values are kept on
 * one line; newlines are replaced with spaces.
 */
object KeyValueText {
    fun encode(vararg pairs: Pair<String, Any?>): String =
        pairs.joinToString("\n") { (key, value) -> "$key=${value?.toString().orEmpty().replace('\n', ' ').replace('\r', ' ')}" }

    fun encode(map: Map<String, Any?>): String = encode(*map.toList().toTypedArray())

    fun decode(text: String): Map<String, String> =
        text.lineSequence()
            .map { it.trim() }
            .filter { it.isNotEmpty() && it.contains('=') }
            .associate { line -> line.substringBefore('=').trim() to line.substringAfter('=').trim() }
}

/** Response to POST [Protocol.OPS]: the revision after applying, and one verdict per operation. */
data class OpsResponse(val serverRevision: Long, val results: Map<String, OpResult>) {
    fun encode(): String {
        val lines = mutableListOf("revision" to serverRevision.toString())
        results.forEach { (opId, result) -> lines += "op.$opId" to result.name }
        return KeyValueText.encode(*lines.toTypedArray())
    }

    companion object {
        fun decode(text: String): OpsResponse {
            val map = KeyValueText.decode(text)
            val revision = map["revision"]?.toLongOrNull() ?: error("ops response without revision")
            val results = map.filterKeys { it.startsWith("op.") }
                .mapKeys { it.key.removePrefix("op.") }
                .mapValues { runCatching { OpResult.valueOf(it.value) }.getOrDefault(OpResult.REJECTED_INVALID) }
            return OpsResponse(revision, results)
        }
    }
}

/** WebSocket notification sent whenever the server revision changes. */
object UpdateMessage {
    fun encode(revision: Long, epoch: String): String = KeyValueText.encode("type" to "revision", "revision" to revision, "epoch" to epoch)

    /** Returns the revision announced by [text], or null if it is not an update message. */
    fun decodeRevision(text: String): Long? {
        val map = KeyValueText.decode(text)
        return if (map["type"] == "revision") map["revision"]?.toLongOrNull() else null
    }
}
